CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash bytea NOT NULL UNIQUE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS households (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id));
CREATE TABLE IF NOT EXISTS people (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), household_id uuid NOT NULL, name text NOT NULL, birth_year int NOT NULL, retirement_year int, death_year int, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id,household_id), FOREIGN KEY(household_id,user_id) REFERENCES households(id,user_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), household_id uuid NOT NULL, name text NOT NULL, kind text NOT NULL CHECK(kind IN ('cash','taxable','tax_deferred','roth')), balance numeric NOT NULL CHECK(balance >= 0), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(household_id,user_id) REFERENCES households(id,user_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS liabilities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), household_id uuid NOT NULL, name text NOT NULL, balance numeric NOT NULL CHECK(balance >= 0), annual_rate numeric NOT NULL DEFAULT 0, annual_payment numeric NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(household_id,user_id) REFERENCES households(id,user_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS incomes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), household_id uuid NOT NULL, person_id uuid, name text NOT NULL, kind text NOT NULL CHECK(kind IN ('social_security','pension','employment','other')), annual_amount numeric NOT NULL, start_year int NOT NULL, end_year int, inflation_rate numeric NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(household_id,user_id) REFERENCES households(id,user_id) ON DELETE CASCADE, FOREIGN KEY(person_id,user_id,household_id) REFERENCES people(id,user_id,household_id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS expenses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), household_id uuid NOT NULL, name text NOT NULL, kind text NOT NULL CHECK(kind IN ('essential','lifestyle','healthcare','one_time')), annual_amount numeric NOT NULL, start_year int NOT NULL, end_year int, inflation_rate numeric NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(household_id,user_id) REFERENCES households(id,user_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS retirement_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), household_id uuid NOT NULL, name text NOT NULL, as_of_year int NOT NULL, end_year int NOT NULL, annual_return numeric NOT NULL, inflation_rate numeric NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id,household_id), FOREIGN KEY(household_id,user_id) REFERENCES households(id,user_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS scenarios (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, household_id uuid NOT NULL, plan_id uuid NOT NULL, name text NOT NULL, overrides jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(household_id,user_id) REFERENCES households(id,user_id) ON DELETE CASCADE, FOREIGN KEY(plan_id,user_id,household_id) REFERENCES retirement_plans(id,user_id,household_id) ON DELETE CASCADE);
